const sumChargesInPeriod = `-- name: SumChargesInPeriod :one
SELECT COALESCE(SUM(amount_cents), 0)::BIGINT AS total_cents
FROM ledger_entries
WHERE tenant_id = $1
  AND user_id = $2
  AND type = 'debit'
  AND created_at >= $3
  AND created_at <= $4
`

type SumChargesInPeriodParams struct {
	TenantID uuid.UUID `json:"tenant_id"`
	UserID   uuid.UUID `json:"user_id"`
	FromTs   time.Time `json:"from_ts"`
	ToTs     time.Time `json:"to_ts"`
}

// : tenant-scoped; total debits for a user in a [from, to] period. The
// : receipt generator uses this for the period's total charged. Cast to
// : BIGINT explicitly so sqlc emits int64.
func (q *Queries) SumChargesInPeriod(ctx context.Context, arg SumChargesInPeriodParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumChargesInPeriod,
		arg.TenantID,
		arg.UserID,
		arg.FromTs,
		arg.ToTs,
	)
	var total_cents int64
	err := row.Scan(&total_cents)
	return total_cents, err
}

const sumLedgerEntriesForUser = `-- name: SumLedgerEntriesForUser :one
SELECT
    (COALESCE(SUM(CASE WHEN type = 'credit' THEN amount_cents ELSE 0 END), 0)
   - COALESCE(SUM(CASE WHEN type = 'debit'  THEN amount_cents ELSE 0 END), 0))::BIGINT
    AS balance_cents
FROM ledger_entries
WHERE tenant_id = $1 AND user_id = $2
`

type SumLedgerEntriesForUserParams struct {
	TenantID uuid.UUID `json:"tenant_id"`
	UserID   uuid.UUID `json:"user_id"`
}

// : tenant-scoped; the authoritative balance computation. Returns the sum
// : of credits - debits in integer centimals. Cast to BIGINT explicitly so
// : sqlc emits int64 (SUM(BIGINT) would otherwise pick the default int32).
func (q *Queries) SumLedgerEntriesForUser(ctx context.Context, arg SumLedgerEntriesForUserParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumLedgerEntriesForUser, arg.TenantID, arg.UserID)
	var balance_cents int64
	err := row.Scan(&balance_cents)
	return balance_cents, err
}

const sumLedgerEntriesForUserUpTo = `-- name: SumLedgerEntriesForUserUpTo :one
SELECT
    (COALESCE(SUM(CASE WHEN type = 'credit' THEN amount_cents ELSE 0 END), 0)
   - COALESCE(SUM(CASE WHEN type = 'debit'  THEN amount_cents ELSE 0 END), 0))::BIGINT
    AS balance_cents
FROM ledger_entries
WHERE tenant_id = $1 AND user_id = $2 AND created_at <= $3
`

type SumLedgerEntriesForUserUpToParams struct {
	TenantID uuid.UUID `json:"tenant_id"`
	UserID   uuid.UUID `json:"user_id"`
	AsOf     time.Time `json:"as_of"`
}

// : tenant-scoped; the balance as-of a timestamp. Used by the receipt
// : generator to compute the period's total charges.
func (q *Queries) SumLedgerEntriesForUserUpTo(ctx context.Context, arg SumLedgerEntriesForUserUpToParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumLedgerEntriesForUserUpTo, arg.TenantID, arg.UserID, arg.AsOf)
	var balance_cents int64
	err := row.Scan(&balance_cents)
	return balance_cents, err
}

const sumUsageEventsForUserInPeriod = `-- name: SumUsageEventsForUserInPeriod :many
SELECT resource_type, unit, SUM(qty) AS total_qty
FROM usage_events
WHERE tenant_id = $1
  AND user_id = $2
  AND started_at >= $3
  AND started_at <= $4
GROUP BY resource_type, unit
`

type SumUsageEventsForUserInPeriodParams struct {
	TenantID uuid.UUID `json:"tenant_id"`
	UserID   uuid.UUID `json:"user_id"`
	FromTs   time.Time `json:"from_ts"`
	ToTs     time.Time `json:"to_ts"`
}

type SumUsageEventsForUserInPeriodRow struct {
	ResourceType string `json:"resource_type"`
	Unit         string `json:"unit"`
	TotalQty     int64  `json:"total_qty"`
}

// : tenant-scoped; the rollup. Returns one row per (resource_type, unit) with
// : the total qty consumed in the [from, to] window. The rollup job then
// : joins this with prices to compute the charge.
func (q *Queries) SumUsageEventsForUserInPeriod(ctx context.Context, arg SumUsageEventsForUserInPeriodParams) ([]SumUsageEventsForUserInPeriodRow, error) {
	rows, err := q.db.Query(ctx, sumUsageEventsForUserInPeriod,
		arg.TenantID,
		arg.UserID,
		arg.FromTs,
		arg.ToTs,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SumUsageEventsForUserInPeriodRow{}
	for rows.Next() {
		var i SumUsageEventsForUserInPeriodRow
		if err := rows.Scan(&i.ResourceType, &i.Unit, &i.TotalQty); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateReceiptPDF = `-- name: UpdateReceiptPDF :exec
UPDATE receipts
SET pdf_bytes = $3, status = 'ready', updated_at = now()
WHERE tenant_id = $1 AND id = $2
`

type UpdateReceiptPDFParams struct {
	TenantID uuid.UUID `json:"tenant_id"`
	ID       uuid.UUID `json:"id"`
	PdfBytes []byte    `json:"pdf_bytes"`
}

// : tenant-scoped; attaches the generated PDF + flips status to ready.
func (q *Queries) UpdateReceiptPDF(ctx context.Context, arg UpdateReceiptPDFParams) error {
	_, err := q.db.Exec(ctx, updateReceiptPDF, arg.TenantID, arg.ID, arg.PdfBytes)
	return err
}

const upsertUserBalance = `-- name: UpsertUserBalance :exec
INSERT INTO user_balances (tenant_id, user_id, balance_cents, currency, last_entry_at, updated_at)
VALUES ($1, $2, $3, $4, $5, now())
ON CONFLICT (tenant_id, user_id) DO UPDATE
SET balance_cents = EXCLUDED.balance_cents,
    currency      = EXCLUDED.currency,
    last_entry_at = EXCLUDED.last_entry_at,
    updated_at    = now()
`

type UpsertUserBalanceParams struct {
	TenantID     uuid.UUID `json:"tenant_id"`
	UserID       uuid.UUID `json:"user_id"`
	BalanceCents int64     `json:"balance_cents"`
	Currency     string    `json:"currency"`
	LastEntryAt  time.Time `json:"last_entry_at"`
}

// : tenant-scoped; atomic cache refresh. amount_cents is the freshly-computed
// : balance; last_entry_at is the timestamp of the ledger entry that produced it.
func (q *Queries) UpsertUserBalance(ctx context.Context, arg UpsertUserBalanceParams) error {
	_, err := q.db.Exec(ctx, upsertUserBalance,
		arg.TenantID,
		arg.UserID,
		arg.BalanceCents,
		arg.Currency,
		arg.LastEntryAt,
	)
	return err
}
